-- ===== U12 vocab 覆盖灌库(volume='9',38词)。分步跑。=====

SELECT 'U12 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U12';

DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U12';
SELECT 'U12 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U12';  -- 应0


SELECT 'U12 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U12';  -- 应38
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U12' GROUP BY word HAVING count(*)>1;  -- 查重应0行